<?php
declare(strict_types=1);
header('X-Content-Type-Options: nosniff'); header('X-Frame-Options: DENY');
header("Content-Security-Policy: default-src 'self'; style-src 'self'; script-src 'self'; form-action 'self'; base-uri 'self'; frame-ancestors 'none'");
session_name('tracer_installer_session');session_set_cookie_params(['httponly'=>true,'samesite'=>'Strict','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();
if(empty($_SESSION['install_csrf']))$_SESSION['install_csrf']=bin2hex(random_bytes(32));
$installed=is_file(__DIR__.'/config/config.php');
$errors=[]; $ok=false;
function h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST' && !$installed){
    if(!hash_equals($_SESSION['install_csrf'],(string)($_POST['install_csrf']??''))){http_response_code(419);exit('Sesi installer tidak valid. Muat ulang halaman.');}
    $host=trim((string)($_POST['host']??'localhost'));
    $port=(int)($_POST['port']??3306);
    $name=trim((string)($_POST['database']??''));
    $user=trim((string)($_POST['username']??''));
    $pass=(string)($_POST['dbpassword']??'');
    $adminName=trim((string)($_POST['admin_name']??''));
    $adminEmail=strtolower(trim((string)($_POST['admin_email']??'')));
    $adminPass=(string)($_POST['admin_password']??'');
    $campus=trim((string)($_POST['campus']??'Tracer Study Kampus'));
    if(!preg_match('/^[a-zA-Z0-9_.-]{1,100}$/',$name))$errors[]='Nama database tidak valid.';
    if(!$host || $port<1||$port>65535||!$user)$errors[]='Konfigurasi server database belum lengkap.';
    if(!$adminName||!filter_var($adminEmail,FILTER_VALIDATE_EMAIL))$errors[]='Identitas administrator tidak valid.';
    if(strlen($adminPass)<12)$errors[]='Password administrator minimal 12 karakter.';
    if(!extension_loaded('pdo_mysql'))$errors[]='Ekstensi pdo_mysql belum aktif di hosting.';
    if(!$errors){
        try {
            $pdo=new PDO("mysql:host=$host;port=$port;dbname=$name;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
            foreach(require __DIR__.'/app/schema.php' as $statement){$pdo->exec($statement);}
            $st=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,\'admin\')');
            $st->execute([$adminName,$adminEmail,password_hash($adminPass,PASSWORD_DEFAULT)]);
            $s=$pdo->prepare('INSERT INTO settings(`key`,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)');
            foreach(['campus_name'=>$campus,'campus_tagline'=>'Jejak Alumni untuk Masa Depan yang Lebih Baik','contact_email'=>$adminEmail,'footer_text'=>'Tracer Study · Evaluasi Mutu Perguruan Tinggi','app_version'=>'1.0.0'] as $k=>$v){$s->execute([$k,$v]);}
            $safe=['db_host'=>$host,'db_port'=>$port,'db_name'=>$name,'db_user'=>$user,'db_pass'=>$pass];
            $file="<?php\n// Generated by installer. Do not expose publicly.\nreturn ".var_export($safe,true).";\n";
            $path=__DIR__.'/config/config.php';
            if(file_put_contents($path,$file,LOCK_EX)===false)throw new RuntimeException('Gagal menulis konfigurasi. Periksa izin folder config/.');
            @chmod($path,0600);
            $ok=true;
        } catch(Throwable $e){$errors[]='Instalasi gagal: '.$e->getMessage();}
    }
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Installer Tracer Study</title><link rel="stylesheet" href="assets/style.css"></head><body class="install-body"><main class="install-panel"><div class="brand-big">🎓 <span>Tracer Study <b>Kampus</b></span></div><p class="muted">Installer lengkap PHP Native · Versi 1.0.0</p>
<?php if($installed || $ok):?><div class="alert alert-success">Instalasi sudah selesai. Untuk keamanan, hapus file <code>install.php</code> dari hosting setelah berhasil.</div><a class="btn btn-primary" href="index.php?page=login">Buka Halaman Login →</a>
<?php else:?><?php foreach($errors as $error):?><div class="alert alert-error"><?=h($error)?></div><?php endforeach;?>
<form method="post" autocomplete="off"><input type="hidden" name="install_csrf" value="<?=h($_SESSION['install_csrf'])?>"><h3>1. Konfigurasi Database MySQL</h3><div class="form-grid"><label>Host<input required name="host" value="<?=h($_POST['host']??'localhost')?>"></label><label>Port<input required name="port" type="number" value="<?=h($_POST['port']??3306)?>"></label><label>Database yang sudah dibuat di cPanel<input required name="database" value="<?=h($_POST['database']??'')?>"></label><label>User database<input required name="username" value="<?=h($_POST['username']??'')?>"></label><label>Password database<input name="dbpassword" type="password"></label></div><h3>2. Identitas Aplikasi & Admin</h3><div class="form-grid"><label>Nama Perguruan Tinggi<input required name="campus" value="<?=h($_POST['campus']??'Tracer Study Kampus')?>"></label><label>Nama Administrator<input required name="admin_name" value="<?=h($_POST['admin_name']??'')?>"></label><label>Email Administrator<input required name="admin_email" type="email" value="<?=h($_POST['admin_email']??'')?>"></label><label>Password Administrator (minimal 12 karakter)<input required name="admin_password" type="password" minlength="12"></label></div><div class="notice">Buat database dan user MySQL terlebih dahulu di cPanel, kemudian berikan seluruh privilege database. Installer tidak membuat database hosting secara otomatis.</div><button class="btn btn-primary" type="submit">Instal Aplikasi Sekarang →</button></form><?php endif;?></main></body></html>
